    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = ((sequence, event.get("revision", 0), pos) if sequence_first
                   else (event.get("revision", 0), pos))
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(n, d=10000):
            return (n + d // 2) // d if mode == "half_up" else n // d

        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = net if discounted else raw
            tax = rounded(base * event.get("tax_bp", 0))
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependencies(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    domains = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, []))
        domains.append([-1] + versions)

    for vector in product(*domains):
        chosen = dict(zip(names, vector))
        chosen = {name: version for name, version in chosen.items() if version != -1}
        if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in chosen and chosen[name] != version for name, version in pins.items()):
            continue

        edges = {}
        valid = True
        for name, version in chosen.items():
            row = next(r for r in packages[name] if r["version"] == version)
            active = [d for d in row.get("deps", [])
                      if not d.get("feature") or d["feature"] in features]
            edges[name] = []
            for dep in active:
                target = dep["name"]
                if target not in chosen or not dep["min"] <= chosen[target] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        visiting, visited = set(), set()
        def visit(name):
            if name in visiting:
                return False
            if name in visited:
                return True
            visiting.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            visiting.remove(name)
            visited.add(name)
            return True

        if any(not visit(name) for name in chosen):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable == set(chosen):
            return {"versions": chosen}
    return {"error": "unsatisfiable"}


def _jobs(data):
    from itertools import combinations

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations([j for j in jobs if j["id"] not in blocked], k):
        ids = {j["id"] for j in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"]))
        if any(a["start"] < b["end"] and b["start"] < a["end"]
               for i, a in enumerate(ordered) for b in ordered[i + 1:]):
            continue
        value = sum(j["value"] for j in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = bit.get(start_node, 0)
    coupons = data["coupons"]
    start_state = (start_node, coupons, initial_mask)
    start_time = data["start"]
    distances = {start_state: start_time}
    queue = [(start_time, start_node, coupons, initial_mask)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, left, mask = heapq.heappop(queue)
        state = (node, left, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(left, edge["duration"])]
            if left:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((left - 1, duration))
            next_mask = mask | bit.get(edge["v"], 0)
            for next_left, duration in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_left, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


